import{_ as a,c as i,o as t,al as s}from"./chunks/framework.CT7RwC5a.js";const p=JSON.parse('{"title":"Adding Standard MAVLink Definitions (Messages/Commands)","description":"","frontmatter":{},"headers":[],"relativePath":"en/mavlink/adding_messages.md","filePath":"en/mavlink/adding_messages.md"}'),n={name:"en/mavlink/adding_messages.md"};function r(o,e,l,d,h,m){return t(),i("div",null,e[0]||(e[0]=[s('<h1 id="adding-standard-mavlink-definitions-messages-commands" tabindex="-1">Adding Standard MAVLink Definitions (Messages/Commands) <a class="header-anchor" href="#adding-standard-mavlink-definitions-messages-commands" aria-label="Permalink to &quot;Adding Standard MAVLink Definitions (Messages/Commands)&quot;">​</a></h1><p>This topic explains how to add new MAVLink messages and commands that are expected to be <em>part of</em> the normal PX4 build.</p><h2 id="standard-mavlink-messages" tabindex="-1">Standard MAVLink Messages <a class="header-anchor" href="#standard-mavlink-messages" aria-label="Permalink to &quot;Standard MAVLink Messages&quot;">​</a></h2><p>The PX4/PX4-Autopilot source code uses only messages that have been standardized by MAVLink. That is to say, the standard definitions in <a href="https://mavlink.io/en/messages/common.html" target="_blank" rel="noreferrer">common.xml</a> in releases, and <a href="https://mavlink.io/en/messages/development.html" target="_blank" rel="noreferrer">development.xml</a> during development. These messages are present in at least one significant flight stack, and members of other flight stacks have accepted them as a reasonable design that would likely be adopted if the same functionality was required.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>A <a href="./../mavlink/custom_messages.html">Custom MAVLink Message</a> is one that isn&#39;t part of the standard. These are defined in your own XML as part of your own fork of PX4. If you use <a href="./../mavlink/custom_messages.html">custom MAVLink messages</a> you will need maintain the definitions in PX4, your ground station, and any other SDKs that communicate with it. Generally you should use (or add to) the standard definitions if at all possible to reduce the maintenance burden.</p></div><p>New standard definitions are added first to <code>development.xml</code>, and then moved to <code>common.xml</code> following review and prototyping, and acceptance by the MAVLink team.</p><p>If you intend your message to become part of the default PX4 build you will need to propose it to the MAVLink community by submitting a pull request (PR) to <a href="https://github.com/mavlink/mavlink/blob/master/message_definitions/v1.0/development.xml" target="_blank" rel="noreferrer">development.xml</a>. The <a href="https://mavlink.io/en/getting_started/" target="_blank" rel="noreferrer">MAVLink Developer guide</a> explains how to define new messages in <a href="https://mavlink.io/en/guide/define_xml_element.html" target="_blank" rel="noreferrer">How to Define MAVLink Messages &amp; Enums</a>.</p><h2 id="generating-message-headers" tabindex="-1">Generating Message Headers <a class="header-anchor" href="#generating-message-headers" aria-label="Permalink to &quot;Generating Message Headers&quot;">​</a></h2><p>During development you can add your definitions to <code>PX4-Autopilot/src/modules/mavlink/mavlink/message_definitions/v1.0/development.xml</code> (or pull them from MAVLink).</p><p>When you build PX4, header files for these message definitions are generated in the build directory (<code>/build/&lt;build target&gt;/mavlink/</code>). If headers are not build for your messages, they may be incorrectly formatted, or use clashing ids. Inspect the build log for information.</p><h2 id="implementing-message-senders-receivers" tabindex="-1">Implementing Message Senders/Receivers <a class="header-anchor" href="#implementing-message-senders-receivers" aria-label="Permalink to &quot;Implementing Message Senders/Receivers&quot;">​</a></h2><p>Once the message headers for your definitions are generated in the PX4 build, you can use them in your code to send and receive the messages:</p><ul><li><a href="./../mavlink/streaming_messages.html">Streaming MAVLink Messages</a></li><li><a href="./../mavlink/receiving_messages.html">Receiving MAVLink Messages</a></li></ul><h2 id="testing" tabindex="-1">Testing <a class="header-anchor" href="#testing" aria-label="Permalink to &quot;Testing&quot;">​</a></h2><p>The first step in debugging is to confirm that any messages you&#39;ve created are being sent/received as you expect.</p><p>You should should first use the <code>uorb top [&lt;message_name&gt;]</code> command to verify in real-time that your message is published and the rate (see <a href="./../middleware/uorb.html#uorb-top-command">uORB Messaging</a>). This approach can also be used to test incoming messages that publish a uORB topic (for other messages you might use <code>printf</code> in your code and test in SITL).</p><p>There are several approaches you can use to view MAVLink traffic:</p><ul><li><p>Create a <a href="https://mavlink.io/en/guide/wireshark.html" target="_blank" rel="noreferrer">Wireshark MAVLink plugin</a> for your dialect. This allows you to inspect MAVLink traffic on an IP interface - for example between <em>QGroundControl</em> or MAVSDK and your real or simulated version of PX4.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>It is much easier to generate a wireshark plugin and inspect traffic in Wireshark, than to rebuild QGroundControl with your dialect and use MAVLink Inspector.</p></div></li><li><p><a href="./../dev_log/logging.html">Log uORB topics</a> associate with your MAVLink message.</p></li><li><p>View received messages in the QGroundControl <a href="https://docs.qgroundcontrol.com/master/en/qgc-user-guide/analyze_view/mavlink_inspector.html" target="_blank" rel="noreferrer">MAVLink Inspector</a>. You will need to <a href="#updating-ground-stations">rebuild QGroundControl with the new message definitions</a>.</p></li></ul><h3 id="set-streaming-rate-using-a-shell" tabindex="-1">Set Streaming Rate using a Shell <a class="header-anchor" href="#set-streaming-rate-using-a-shell" aria-label="Permalink to &quot;Set Streaming Rate using a Shell&quot;">​</a></h3><p>For testing, it is sometimes useful to increase the streaming rate of individual topics at runtime (e.g. for inspection in QGC). This can be achieved using by calling the <a href="./../modules/modules_communication.html#mavlink">mavlink</a> module through the <a href="https://docs.qgroundcontrol.com/master/en/qgc-user-guide/analyze_view/mavlink_console.html" target="_blank" rel="noreferrer">QGC MAVLink console</a> (or some other shell):</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mavlink</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stream</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">port</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> numbe</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">r</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">mavlink</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> topic</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nam</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">rat</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p>You can get the port number with <code>mavlink status</code> which will output (amongst others) <code>transport protocol: UDP (&lt;port number&gt;)</code>. An example would be:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mavlink</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stream</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 14556</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> CA_TRAJECTORY</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 300</span></span></code></pre></div><h2 id="updating-ground-stations" tabindex="-1">Updating Ground Stations <a class="header-anchor" href="#updating-ground-stations" aria-label="Permalink to &quot;Updating Ground Stations&quot;">​</a></h2><p>Ultimately you&#39;ll want to use your new MAVLink interface by providing the corresponding ground station or MAVSDK implementation.</p><p>The important thing to remember here is that MAVLink requires that you use a version of the library that is built to the same definition (XML file). So if you have created a custom message in PX4 you won&#39;t be able to use it unless you build QGC or MAVSDK with that same definition.</p><h3 id="updating-qgroundcontrol" tabindex="-1">Updating QGroundControl <a class="header-anchor" href="#updating-qgroundcontrol" aria-label="Permalink to &quot;Updating QGroundControl&quot;">​</a></h3><p>You will need to <a href="https://docs.qgroundcontrol.com/master/en/qgc-dev-guide/getting_started/index.html" target="_blank" rel="noreferrer">Build QGroundControl</a> including a pre-built C library that contains your custom messages.</p><p>QGC uses a pre-built C library that must be located at <a href="https://github.com/mavlink/qgroundcontrol/tree/master/libs/mavlink/include/mavlink" target="_blank" rel="noreferrer">/qgroundcontrol/libs/mavlink/include/mavlink</a> in the QGC source.</p><p>By default this is pre-included as a submodule from <a href="https://github.com/mavlink/c_library_v2" target="_blank" rel="noreferrer">https://github.com/mavlink/c_library_v2</a> but you can <a href="https://mavlink.io/en/getting_started/generate_libraries.html" target="_blank" rel="noreferrer">generate your own MAVLink Libraries</a>.</p><p>QGC uses the <strong>all.xml</strong> dialect by default, which includes <strong>common.xml</strong>. You can include your messages in either file.</p><p>Note that if you use your own <em>custom dialect</em> then it should include <strong>ArduPilotMega.xml</strong> (or it will miss all the existing messages), and you will need to change the dialect used by setting it in <a href="https://github.com/mavlink/qgroundcontrol/blob/master/QGCExternalLibs.pri#L52" target="_blank" rel="noreferrer"><code>MAVLINK_CONF</code></a> when running <em>qmake</em>.</p><h3 id="updating-mavsdk" tabindex="-1">Updating MAVSDK <a class="header-anchor" href="#updating-mavsdk" aria-label="Permalink to &quot;Updating MAVSDK&quot;">​</a></h3><p>See the MAVSDK docs for information about how to work with <a href="https://mavsdk.mavlink.io/main/en/cpp/guide/build.html" target="_blank" rel="noreferrer">MAVLink headers and dialects</a>.</p>',34)]))}const u=a(n,[["render",r]]);export{p as __pageData,u as default};
